INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'forehead', 'n.', '/ˈfɒrɪd/', '额,前额', 'Before her speech, Zhang Yue wiped the sweat from her forehead.', '演讲前,张悦擦去额头上的汗。', 'Business Blossoms', 1, 0, 'senior', 'wordlist', 'elective4', 'U4', 'wipe one''s forehead', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'blank', 'adj.', '/blæŋk/', '无表情的,茫然的;空白的', 'The investors stared back with blank faces, giving no clue what they thought.', '投资人面无表情地回望,让人猜不透他们的想法。', 'Business Blossoms', 2, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a blank face', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dizzy', 'adj.', '/ˈdɪzi/', '头晕目眩的', 'Feeling dizzy with fear, she took a deep breath and finished her business plan.', '因恐惧而头晕的她深吸一口气,讲完了商业计划。', 'Business Blossoms', 3, 0, 'senior', 'wordlist', 'elective4', 'U4', 'feel dizzy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'chairwoman', 'n.', '/ˈtʃeəˌwʊmən/', '女主席;女会长', 'She is now the chairwoman of her own rose company.', '她如今是自己玫瑰公司的女会长。', 'Business Blossoms', 4, 0, 'senior', 'wordlist', 'elective4', 'U4', 'chairwoman of a company', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sunrise', 'n.', '/ˈsʌnraɪz/', '日出;黎明', 'The workers pick the delicate flowers before sunrise.', '工人们在日出前采摘娇嫩的花朵。', 'Business Blossoms', 5, 0, 'senior', 'wordlist', 'elective4', 'U4', 'before sunrise', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'potential', 'n.', '/pəˈtenʃ(ə)l/', '潜力,可能性', 'Only after returning home did she realise the business potential of roses.', '直到回到家乡,她才意识到玫瑰的商业潜力。', 'Business Blossoms', 6, 0, 'senior', 'wordlist', 'elective4', 'U4', 'see the potential', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bug', 'n.', '/bʌɡ/', '突然的兴趣,迷恋', 'Like many young people, she was bitten by the start-up bug.', '和许多年轻人一样,她迷上了创业。', 'Business Blossoms', 7, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the start-up bug', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'enterprising', 'adj.', '/ˈentəpraɪzɪŋ/', '有创业精神的,有进取心的', 'More enterprising young people are thinking of starting their own businesses.', '越来越多有创业精神的年轻人想自己创业。', 'Business Blossoms', 8, 0, 'senior', 'wordlist', 'elective4', 'U4', 'an enterprising young person', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'input', 'n.', '/ˈɪnpʊt/', '投入(物);投入的资源', 'Experienced business people gave her important input and support.', '经验丰富的商人给了她重要的投入和支持。', 'Business Blossoms', 9, 0, 'senior', 'wordlist', 'elective4', 'U4', 'valuable input', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'obstacle', 'n.', '/ˈɒbstək(ə)l/', '障碍,阻碍', 'She has overcome a number of obstacles to make her business succeed.', '她克服了许多障碍,使生意取得成功。', 'Business Blossoms', 10, 0, 'senior', 'wordlist', 'elective4', 'U4', 'overcome an obstacle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'phase', 'n.', '/feɪz/', '阶段,时期', 'The biggest challenge at the initial phase was hiring workers.', '起步阶段最大的挑战是雇人。', 'Business Blossoms', 11, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the initial phase', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'manufacturer', 'n.', '/ˌmænjʊˈfæktʃ(ə)rə/', '制造商,生产厂家', 'A major manufacturer of cosmetics offered to buy her product.', '一家大型化妆品制造商提出购买她的产品。', 'Business Blossoms', 12, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a large manufacturer', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'cosmetics', 'n.', '/kɒzˈmetɪks/', '化妆品,美容品', 'The company uses her roses to make expensive cosmetics.', '这家公司用她的玫瑰制作昂贵的化妆品。', 'Business Blossoms', 13, 0, 'senior', 'wordlist', 'elective4', 'U4', 'make cosmetics', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'purchase', 'v.', '/ˈpɜːtʃəs/', '购买', 'The manufacturer was willing to purchase her product and help sell it.', '制造商愿意购买她的产品并帮忙销售。', 'Business Blossoms', 14, 0, 'senior', 'wordlist', 'elective4', 'U4', 'purchase a product', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'distribution', 'n.', '/ˌdɪstrɪˈbjuːʃ(ə)n/', '分销,经销', 'A big partner helped her with the distribution of the roses.', '一个大合作伙伴帮她做玫瑰的分销。', 'Business Blossoms', 15, 0, 'senior', 'wordlist', 'elective4', 'U4', 'help with distribution', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bonus', 'n.', '/ˈbəʊnəs/', '奖金;红利', 'This year she can pay every worker a decent bonus.', '今年她能给每位工人发一笔可观的奖金。', 'Business Blossoms', 16, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a decent bonus', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'entrepreneurial', 'adj.', '/ˌɒntrəprəˈnɜːriəl/', '创业的,有创业精神的', 'She welcomes the new entrepreneurial spirit among young people.', '她欢迎年轻人中新兴的创业精神。', 'Business Blossoms', 17, 0, 'senior', 'wordlist', 'elective4', 'U4', 'entrepreneurial spirit', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'guidance', 'n.', '/ˈɡaɪd(ə)ns/', '指导,引导', 'She advises young people to seek guidance from experts first.', '她建议年轻人先向专家寻求指导。', 'Business Blossoms', 18, 0, 'senior', 'wordlist', 'elective4', 'U4', 'seek guidance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'consultant', 'n.', '/kənˈsʌltənt/', '顾问', 'Before starting out, ask an experienced consultant for advice.', '在起步之前,向有经验的顾问请教。', 'Business Blossoms', 19, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a business consultant', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'conventional', 'adj.', '/kənˈvenʃ(ə)nəl/', '传统的,常规的', 'Fair-trade prices are higher than under the conventional trading system.', '公平贸易的价格高于传统贸易体系下的价格。', 'Business Blossoms', 20, 0, 'senior', 'wordlist', 'elective4', 'U4', 'the conventional way', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'discriminate', 'v.', '/dɪˈskrɪmɪneɪt/', '歧视;区别对待', 'Some argue that the system discriminates against producers outside it.', '有人认为这一制度歧视体系外的生产者。', 'Business Blossoms', 21, 0, 'senior', 'wordlist', 'elective4', 'U4', 'discriminate against', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'equator', 'n.', '/ɪˈkweɪtə/', '赤道', 'The coffee is grown on an estate close to the equator.', '这种咖啡产于赤道附近的庄园。', 'Business Blossoms', 22, 0, 'senior', 'wordlist', 'elective4', 'U4', 'near the equator', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'estate', 'n.', '/ɪˈsteɪt/', '庄园;大片土地', 'The beans are grown on the Green Equator Estate.', '咖啡豆产于绿赤道庄园。', 'Business Blossoms', 23, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a coffee estate', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'superior', 'adj.', '/suːˈpɪəriə/', '质量上乘的,优质的', 'Customers love the superior, smooth flavour of the product.', '顾客喜爱这款产品上乘而顺滑的口感。', 'Business Blossoms', 24, 0, 'senior', 'wordlist', 'elective4', 'U4', 'superior quality', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'mild', 'adj.', '/maɪld/', '不浓烈的,温和的', 'The coffee has a smooth blend with a mild flavour.', '这款咖啡口感顺滑,味道不浓烈。', 'Business Blossoms', 25, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a mild flavour', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'calorie', 'n.', '/ˈkæləri/', '卡(路里)', 'Each cup contains less than one calorie.', '每杯所含热量不到一卡路里。', 'Business Blossoms', 26, 0, 'senior', 'wordlist', 'elective4', 'U4', 'less than one calorie', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'subjective', 'adj.', '/səbˈdʒektɪv/', '主观的', 'In the past, lenders relied mainly on their subjective judgement.', '过去,放贷者主要依靠自己的主观判断。', 'Business Blossoms', 27, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a subjective judgement', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'freshman', 'n.', '/ˈfreʃmən/', '(大学)一年级学生', 'As a freshman, you must handle your own money for the first time.', '作为大一新生,你要第一次自己管理钱。', 'Business Blossoms', 28, 0, 'senior', 'wordlist', 'elective4', 'U4', 'a college freshman', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'afloat', 'adj.', '/əˈfləʊt/', '不欠债的,经济上周转得开的', 'Here are some tips to help students stay afloat.', '这里有一些帮助学生不欠债的建议。', 'Business Blossoms', 29, 0, 'senior', 'wordlist', 'elective4', 'U4', 'stay afloat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'interfere', 'v.', '/ˌɪntəˈfɪə/', '干涉,妨碍', 'Make sure a part-time job does not interfere with your studies.', '确保兼职工作不妨碍你的学业。', 'Business Blossoms', 30, 0, 'senior', 'wordlist', 'elective4', 'U4', 'interfere with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'rational', 'adj.', '/ˈræʃ(ə)nəl/', '理性的,合理的', 'Always make rational spending choices and avoid luxuries.', '始终做出理性的消费选择,避免奢侈品。', 'Business Blossoms', 31, 0, 'senior', 'wordlist', 'elective4', 'U4', 'rational spending', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'exceed', 'v.', '/ɪkˈsiːd/', '超过,超出', 'Never exceed your agreed credit limit.', '切勿超出你约定的信用额度。', 'Business Blossoms', 32, 0, 'senior', 'wordlist', 'elective4', 'U4', 'exceed the limit', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'financial', 'adj.', '/fɪˈnænʃ(ə)l/', '财政的,金融的;财务的', 'Good financial management is a useful skill for life.', '良好的财务管理是一项终身受用的技能。', 'Business Blossoms', 33, 0, 'senior', 'wordlist', 'elective4', 'U4', 'financial management', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'accumulate', 'v.', '/əˈkjuːmjəleɪt/', '积累,积聚', 'Save a little each week, and your money will accumulate over time.', '每周存一点,你的钱会随时间积累起来。', 'Business Blossoms', 34, 0, 'senior', 'wordlist', 'elective4', 'U4', 'accumulate savings', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'automatically', 'adv.', '/ˌɔːtəˈmætɪkli/', '自动地', 'Annual fees are charged automatically to your credit card.', '年费会自动从你的信用卡扣除。', 'Business Blossoms', 35, 0, 'senior', 'wordlist', 'elective4', 'U4', 'charged automatically', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'toddler', 'n.', '/ˈtɒdlə/', '学步的儿童', 'Since we were toddlers, we have been told that it is good to share.', '从蹒跚学步起,我们就被告知分享是好事。', 'Business Blossoms', 36, 0, 'senior', 'wordlist', 'elective4', 'U4', 'since we were toddlers', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'sorrow', 'n.', '/ˈsɒrəʊ/', '悲伤;伤心事', 'We share toys, snacks and sometimes even sorrow with others.', '我们与他人分享玩具、零食,有时甚至分享悲伤。', 'Business Blossoms', 37, 0, 'senior', 'wordlist', 'elective4', 'U4', 'share sorrow', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'frustration', 'n.', '/frʌˈstreɪʃ(ə)n/', '懊丧,沮丧', 'Sharing is not just about sweets; it can also ease our frustration.', '分享不只是关于糖果,它也能缓解我们的沮丧。', 'Business Blossoms', 38, 0, 'senior', 'wordlist', 'elective4', 'U4', 'share frustration', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'hire', 'v.', '/haɪə/', '租用;雇用', 'With a phone you can hire a bike for the whole afternoon.', '用手机你可以租一辆自行车骑一下午。', 'Business Blossoms', 39, 0, 'senior', 'wordlist', 'elective4', 'U4', 'hire a bike', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'thereby', 'adv.', '/ðeəˈbaɪ/', '因此,由此', 'Sharing encourages people to reuse items, thereby cutting down on waste.', '分享鼓励人们重复使用物品,由此减少浪费。', 'Business Blossoms', 40, 0, 'senior', 'wordlist', 'elective4', 'U4', 'thereby cutting waste', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'supervision', 'n.', '/ˌsuːpəˈvɪʒ(ə)n/', '监督;管理', 'The sharing economy grows faster than existing rules or supervision.', '共享经济的发展快于现有规则或监管。', 'Business Blossoms', 41, 0, 'senior', 'wordlist', 'elective4', 'U4', 'under supervision', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'expense', 'n.', '/ɪkˈspens/', '费用,花费', 'Some firms expand at the expense of more traditional companies.', '一些公司以损害传统企业为代价来扩张。', 'Business Blossoms', 42, 0, 'senior', 'wordlist', 'elective4', 'U4', 'at the expense of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'abuse', 'n.', '/əˈbjuːs/', '滥用', 'The sharing economy is sometimes subject to abuse of trust.', '共享经济有时会遭遇信任的滥用。', 'Business Blossoms', 43, 0, 'senior', 'wordlist', 'elective4', 'U4', 'abuse of trust', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'theft', 'n.', '/θeft/', '偷窃,偷盗', 'Some users have become victims of theft while sharing rides.', '一些用户在拼车时成了盗窃的受害者。', 'Business Blossoms', 44, 0, 'senior', 'wordlist', 'elective4', 'U4', 'victim of theft', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'purse', 'n.', '/pɜːs/', '(女式)钱包', 'With phone payment, you never worry about losing your purse.', '用手机支付,你再也不必担心丢钱包。', 'Business Blossoms', 45, 0, 'senior', 'wordlist', 'elective4', 'U4', 'lose one''s purse', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u4.01', '①关系代词 who/whom/which/that/whose(限制性)', 'A2', 12, '外研社版选择性必修第四册 U4 — 先行词指人用 who(主)/whom(宾);指物用 which;所有格用 whose;先行词被 all/everything/the only/序数词修饰或为不定代词时只能用 that。', 1, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u4.02', '②关系副词 when/where/why 与介词+which', 'A2', 12, '外研社版选择性必修第四册 U4 — 从句只缺状语时:时间用 when(=on/in which)、地点用 where(=in/at which)、原因用 why(=for which);介词后只能用 which,不用 where/when/that。', 2, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe4u4.03', '③非限制性定语从句(逗号 + which/who/whose · 整句指代 · of which/whom · as)', 'A2', 12, '外研社版选择性必修第四册 U4 — 逗号后非限制性从句指人用 who/whom、指物用 which、所有格用 whose,绝不用 that;which 可指代前面整句话;"of which/whom"表部分;"As is known"为固定 as 从句。', 3, 'elective4', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The entrepreneur ____ started the rose farm is now famous all over Asia.', 'who', 'which', 'whose', 'where', 'A', '先行词 entrepreneur 指人、从句缺主语 → 用指人的关系代词 who。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The investors ____ we met in the studio liked her business plan.', 'which', 'whom', 'whose', 'where', 'B', '先行词 investors 指人、在从句中作 met 的宾语、且要排除 who/that → 用 whom。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'A bonus is money ____ rewards workers for their hard effort.', 'who', 'whose', 'which', 'where', 'C', '先行词 money 指物、从句缺主语、不与 who 同现 → 用指物的 which。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The company ____ products sell well across Asia is hiring more staff.', 'which', 'who', 'where', 'whose', 'D', '先行词 company、从句缺 products 前的所有格(公司的产品)→ 用 whose。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The customers ____ bought her roses last spring came back again.', 'who', 'which', 'whose', 'when', 'A', '先行词 customers 指人、从句缺主语 → 用 who。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'This is the manager ____ trained all the new workers at the farm.', 'which', 'who', 'whose', 'where', 'B', '先行词 manager 指人、从句缺主语 → 用 who。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The flowers ____ the workers pick before sunrise are very fresh.', 'who', 'whose', 'which', 'when', 'C', '先行词 flowers 指物、从句缺 pick 的宾语 → 用 which。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The worker ____ idea saved the company money got a reward.', 'which', 'who', 'where', 'whose', 'D', '先行词 worker、从句缺 idea 前的所有格(工人的主意)→ 用 whose。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The plan ____ she presented on television finally won support.', 'which', 'who', 'whose', 'when', 'A', '先行词 plan 指物、从句缺 presented 的宾语 → 用 which。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'There is the consultant ____ gave the young owner useful advice.', 'which', 'who', 'whose', 'where', 'B', '先行词 consultant 指人、从句缺主语 → 用 who。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The farmers ____ she hired last year all work very hard.', 'which', 'whose', 'whom', 'where', 'C', '先行词 farmers 指人、在从句中作 hired 的宾语、排除 who/that → 用 whom。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The product ____ won the prize is completely organic.', 'who', 'whose', 'where', 'which', 'D', '先行词 product 指物、从句缺主语、不与 who 同现 → 用 which。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The girl ____ parents grow roses decided to study business.', 'whose', 'which', 'who', 'where', 'A', '先行词 girl、从句缺 parents 前的所有格(女孩的父母)→ 用 whose。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'Everything ____ he said about the profit later proved true.', 'which', 'that', 'who', 'what', 'B', '先行词为不定代词 everything,定语从句只能用 that,不用 which。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'It was the only shop ____ stayed open after midnight.', 'which', 'who', 'that', 'where', 'C', '先行词被 the only 修饰时,定语从句只能用 that。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The first customer ____ arrived in the morning got a free rose.', 'which', 'whose', 'where', 'that', 'D', '先行词被序数词 the first 修饰时,用 that 引导定语从句。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'All ____ glitters is not gold, as the old saying goes.', 'that', 'which', 'who', 'what', 'A', '先行词为不定代词 all,定语从句用 that,不用 which。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The brand ____ name is well known now sells abroad.', 'which', 'whose', 'who', 'where', 'B', '先行词 brand、从句缺 name 前的所有格(品牌的名字)→ 用 whose。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The team ____ he leads meets in the field every morning.', 'who', 'whose', 'which', 'when', 'C', '先行词 team 指物(机构)、从句缺 leads 的宾语 → 用 which。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.01'), 'The investor ____ we trusted most offered the largest sum.', 'which', 'whose', 'where', 'whom', 'D', '先行词 investor 指人、作 trusted 的宾语、排除 who/that → 用 whom。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'This is the valley ____ roses grow wild all year round.', 'where', 'which', 'when', 'why', 'A', '先行词 valley 表地点、从句不缺主宾(只缺地点状语)→ 用关系副词 where(= in which)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'I will never forget the day ____ I started my own business.', 'where', 'when', 'why', 'which', 'B', '先行词 day 表时间、从句只缺时间状语 → 用关系副词 when(= on which)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'That is the reason ____ she decided to return to her home town.', 'when', 'where', 'why', 'which', 'C', '先行词 reason 表原因、从句缺原因状语 → 用关系副词 why(= for which)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'The town ____ she grew up has become famous for its roses.', 'which', 'when', 'why', 'where', 'D', '先行词 town 表地点、从句只缺地点状语 → 用 where。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), '2017 was the year ____ her small company was set up.', 'when', 'where', 'why', 'which', 'A', '先行词 year 表时间、从句只缺时间状语 → 用 when。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'Tell me the reason ____ the roses must be picked before sunrise.', 'when', 'why', 'where', 'which', 'B', '先行词 reason、从句缺原因状语 → 用 why。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'This is the little shop ____ we buy fresh flowers every week.', 'which', 'when', 'where', 'why', 'C', '先行词 shop 表地点、从句只缺地点状语 → 用 where。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'There was a moment ____ everyone in the village doubted her.', 'where', 'why', 'which', 'when', 'D', '先行词 moment 表时间、从句只缺时间状语 → 用 when。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'The greenhouse in ____ the roses grow stays warm in winter.', 'which', 'where', 'that', 'when', 'A', '介词 in 后只能用 which,不能用 where/that;in which = where。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'The early morning on ____ we pick the flowers is always busy.', 'when', 'which', 'where', 'that', 'B', '介词 on 后只能用 which,不能用 when/that;on which = when。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'This is the office ____ she makes all the big decisions.', 'which', 'when', 'where', 'why', 'C', '先行词 office 表地点、从句只缺地点状语 → 用 where。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'Do you remember the date ____ the big order was signed?', 'where', 'why', 'which', 'when', 'D', '先行词 date 表时间、从句只缺时间状语 → 用 when。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'The market ____ she sells her roses opens early at dawn.', 'where', 'which', 'when', 'why', 'A', '先行词 market 表地点、从句只缺地点状语 → 用 where。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'The day on ____ the TV show aired changed her whole life.', 'when', 'which', 'where', 'that', 'B', '介词 on 后只能用 which;on which = when。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'He carefully explained the reason ____ the profits had fallen.', 'when', 'where', 'why', 'which', 'C', '先行词 reason、从句缺原因状语 → 用 why。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'The village ____ she was born now grows roses for export.', 'which', 'when', 'why', 'where', 'D', '先行词 village 表地点、从句只缺地点状语 → 用 where。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'The week ____ the first orders arrived was extremely busy.', 'when', 'where', 'why', 'which', 'A', '先行词 week 表时间、从句只缺时间状语 → 用 when。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'There are times ____ running your own business feels very hard.', 'where', 'when', 'why', 'which', 'B', '先行词 times 表时间、从句只缺时间状语 → 用 when。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'The house in ____ she now lives is close to the rose fields.', 'where', 'that', 'which', 'when', 'C', '介词 in 后只能用 which;in which = where。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.02'), 'This is the city ____ many young start-ups first begin.', 'which', 'when', 'why', 'where', 'D', '先行词 city 表地点、从句只缺地点状语 → 用 where。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'Zhang Yue, ____ grew up among roses, started her own farm.', 'who', 'that', 'which', 'whom', 'A', '非限制性定语从句指人作主语,只能用 who;非限制性中不用 that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'She decided to grow roses, ____ surprised many of her friends.', 'that', 'which', 'what', 'who', 'B', '关系词指代前面整句话、引导非限制性从句作主语 → 用 which。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'My boss, ____ I respect very much, gave me a generous bonus.', 'that', 'which', 'whom', 'what', 'C', '非限制性从句中指人作宾语 → 用 whom;非限制性不用 that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'The roses, ____ smell is wonderful, sell out almost every day.', 'which', 'that', 'who', 'whose', 'D', '非限制性从句缺 smell 前的所有格(玫瑰的香味)→ 用 whose。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'Mr Li, ____ company makes cosmetics, bought her whole crop.', 'whose', 'which', 'that', 'who', 'A', '非限制性从句缺 company 前的所有格(李先生的公司)→ 用 whose。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'The deal suddenly failed, ____ disappointed the whole team.', 'that', 'which', 'what', 'who', 'B', '关系词指代前面整句话、引导非限制性从句作主语 → 用 which。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'She hired ten workers, all of ____ came from the same village.', 'which', 'that', 'whom', 'who', 'C', '"all of + 关系代词"指人 → 用 whom(all of whom)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'He gave several reasons, none of ____ really convinced us.', 'whom', 'that', 'what', 'which', 'D', '"none of + 关系代词"指物(reasons)→ 用 which(none of which)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'The factory has fifty machines, most of ____ are brand new.', 'which', 'whom', 'that', 'what', 'A', '"most of + 关系代词"指物(machines)→ 用 which(most of which)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'Her parents, ____ still grow roses, are very proud of her.', 'that', 'who', 'which', 'whom', 'B', '非限制性从句指人作主语 → 用 who。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'He invested all his savings, ____ was a very brave choice.', 'that', 'what', 'which', 'who', 'C', '关系词指代前面整句话、引导非限制性从句作主语 → 用 which。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'The manager, ____ we all trust completely, made the final call.', 'that', 'which', 'what', 'whom', 'D', '非限制性从句指人作宾语 → 用 whom。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'Our products, ____ quality is high, are now sold overseas.', 'whose', 'which', 'that', 'who', 'A', '非限制性从句缺 quality 前的所有格(产品的质量)→ 用 whose。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), '____ is well known, running a small business is never easy.', 'Which', 'As', 'That', 'What', 'B', '"As is well known"为固定的 as 引导的非限制性从句,放句首,which 不能放句首。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'She works extremely hard, ____ we all greatly admire.', 'that', 'who', 'which', 'what', 'C', '关系词指代前面整件事、引导非限制性从句作 admire 的宾语 → 用 which。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'Tom, ____ father runs a bank, knows a lot about money.', 'which', 'that', 'who', 'whose', 'D', '非限制性从句缺 father 前的所有格(汤姆的父亲)→ 用 whose。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'The shop sells roses, ____ are all grown on a local farm.', 'which', 'that', 'who', 'whose', 'A', '非限制性从句指物(roses)作主语 → 用 which;非限制性不用 that。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'There were many guests, some of ____ were rich investors.', 'which', 'whom', 'that', 'who', 'B', '"some of + 关系代词"指人(guests)→ 用 whom(some of whom)。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'The new plan worked very well, ____ pleased everyone at work.', 'that', 'what', 'which', 'who', 'C', '关系词指代前面整句话、引导非限制性从句作主语 → 用 which。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective4' AND unit='U4' AND code='fe4u4.03'), 'Mary, ____ I met at the flower fair, runs a small shop.', 'that', 'which', 'what', 'whom', 'D', '非限制性从句指人作 met 的宾语 → 用 whom。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'From Roses to Riches', 'Zhang Yue is the chairwoman of a company that grows roses in a quiet valley far from any city. Before sunrise, she walks between the rows of rose plants, where the workers she hires will soon pick the delicate flowers. Zhang did not always plan this life. She grew up surrounded by roses but paid them little attention. It was only after she returned from studying overseas that she saw their potential. "Conditions here are ideal," she says. "This is a place where roses grow wild." She then decided to return to her home town and start a business, which surprised many people. The biggest challenge at the early phase was to persuade local people to work for her, because few believed she could build a successful business from flowers. After she appeared on television, a large company offered to purchase her product and help with its distribution. Today her roses are among the best in Asia, and she can pay every worker a fair bonus.', '记叙·玫瑰创业故事', 166, '[{"q":"Why did Zhang Yue decide to go back to her home town?","answer":"A","options":["To set up a rose-growing business there.","To work in a television studio.","To study at a university overseas.","To buy flowers for a big company."],"explanation":"原文说她回乡 start a business(种玫瑰)的转述。"},{"q":"What was the hardest thing for Zhang at the start?","answer":"B","options":["Finding a valley with wild roses.","Getting local people to come and work for her.","Learning how to grow flowers.","Travelling to a foreign country."],"explanation":"对 ''persuade local people to work for her'' 的概括转述。"},{"q":"What happened after Zhang appeared on television?","answer":"A","options":["A big company agreed to buy and distribute her roses.","She gave up the rose business completely.","Her workers all decided to leave.","She moved away from the valley."],"explanation":"对 ''a large company offered to purchase her product and help with its distribution'' 的转述。"}]'::jsonb, '[{"word":"chairwoman","cn":"女会长"},{"word":"potential","cn":"潜力"},{"word":"phase","cn":"阶段"},{"word":"bonus","cn":"奖金"}]'::jsonb, 2, 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Sharing Instead of Buying', 'The sharing economy is changing the way people use goods and services. Instead of buying things they rarely need, many people now borrow or rent them for a short time. These range from car shares to home shares, and even to shared power banks. With a single click on a phone, a person can hire a bike for an afternoon or rent out a spare room for a few days. Whether you are a lender or a borrower, it can be a win-win situation, because everyone makes or saves money. Sharing also encourages people to reuse items, which cuts down on waste, and bike and car sharing reduce the number of polluting cars on the road. However, the system is not perfect. It is growing faster than the rules that control it, and personal data is not always safe. Even so, the sharing economy is becoming more and more important to our daily lives and to the wider economy.', '说明·共享经济', 159, '[{"q":"What is the passage mainly about?","answer":"B","options":["How to make roses grow faster.","How the sharing economy works and what it brings.","Why people should always buy new things.","How banks lend money to companies."],"explanation":"全文围绕共享经济的运作与影响。"},{"q":"According to the text, how does sharing help the environment?","answer":"C","options":["It makes everyone buy more goods.","It builds more factories quickly.","It cuts waste and puts fewer cars on the road.","It stops people from using phones."],"explanation":"对 ''reuse items... cuts down on waste'' 和 ''reduce... cars'' 的转述。"},{"q":"What problem with the sharing economy is mentioned?","answer":"D","options":["Nobody is willing to share anything.","It is far too slow to grow.","It only works for very rich people.","Rules cannot keep up, and personal data may be unsafe."],"explanation":"对 ''growing faster than the rules... personal data is not always safe'' 的转述。"}]'::jsonb, '[{"word":"hire","cn":"租用"},{"word":"lender","cn":"出借者"},{"word":"waste","cn":"浪费"}]'::jsonb, 2, 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Fairer Deal for Farmers', 'Good Deal is a movement that helps farmers and workers in less developed areas get a fairer price for what they produce. Good Deal products, such as coffee or chocolate, may cost a little more than ordinary ones. However, up to one third of the sale price is returned to the producers, which is far more than they would earn under the usual trading system. The movement has become popular among young shoppers, who are happy to spend a bit more to support distant farmers. They believe that buying these products helps improve local people''s lives. Not everyone agrees, though. Some people argue that the system is unfair to producers who are not part of the movement, because their goods may be ignored. Supporters reply that the aim is to share wealth more evenly, and that every small choice by a shopper can make a real difference to a family far away.', '说明·公平贸易', 152, '[{"q":"What is special about the price of Good Deal products?","answer":"A","options":["A large share of it is paid back to the producers.","It is always lower than ordinary products.","It never changes from year to year.","It is set only by the shoppers."],"explanation":"对 ''one third of the sale price is returned to the producers'' 的转述。"},{"q":"Why do many young shoppers buy these products?","answer":"B","options":["Because they are the cheapest goods around.","To support farmers in poorer areas.","Because the law forces them to.","To save time when shopping online."],"explanation":"对 ''happy to spend a bit more to support distant farmers'' 的转述。"},{"q":"What do critics of the movement say?","answer":"C","options":["It pays farmers far too much money.","It is loved by absolutely everyone.","It may be unfair to producers outside it.","It only sells flowers, not coffee."],"explanation":"对 ''unfair to producers who are not part of the movement'' 的转述。"}]'::jsonb, '[{"word":"producer","cn":"生产者"},{"word":"conventional","cn":"传统的"}]'::jsonb, 2, 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'What Your Score Says About You', 'A social credit system records how honest and reliable people are in their daily activities. When a person pays bills on time, returns library books promptly and keeps promises, their credit score goes up. A good score can bring real rewards. In some cities, people with high scores do not have to pay a deposit when they book a hotel or hire a shared bike. A poor record, on the other hand, can make life harder. Someone with many unpaid debts may be stopped from buying expensive train tickets or borrowing money from a bank. Supporters say the system encourages people to behave well and to keep their word, which makes society more trustworthy. Others worry that it collects too much personal information, and that mistakes in the records may be hard to correct. Whatever people think, more and more services now check a person''s credit before offering a loan or a deal.', '说明·社会信用', 153, '[{"q":"How can a person make their credit score go up?","answer":"D","options":["By spending as much money as possible.","By borrowing from many banks at once.","By never using any services at all.","By paying on time and keeping their promises."],"explanation":"对 ''pays bills on time... keeps promises'' 的转述。"},{"q":"What benefit can a high credit score bring?","answer":"A","options":["Skipping the deposit when booking a hotel or bike.","Free train tickets for life.","A larger house from the government.","A higher salary at work."],"explanation":"对 ''do not have to pay a deposit when they book a hotel or hire a shared bike'' 的转述。"},{"q":"What worry about the system does the text mention?","answer":"B","options":["It is far too easy to cheat.","It gathers too much data, and errors are hard to fix.","It gives money to everyone equally.","It only works in the countryside."],"explanation":"对 ''collects too much personal information... mistakes... hard to correct'' 的转述。"}]'::jsonb, '[{"word":"credit score","cn":"信用分"},{"word":"deposit","cn":"押金"},{"word":"trustworthy","cn":"可信赖的"}]'::jsonb, 2, 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Money Tips for New Students', 'For many students, university is the first time they must handle money on their own. Learning a few simple habits early can help them make ends meet and avoid going into debt. First, it is wise to choose a bank account with no hidden fees and free online services. Second, students should start saving a small amount each week and slowly increase it, because even tiny savings grow over time and earn interest. Building good credit also matters, so any credit card should be used carefully and every bill paid on time. Making extra money is fine, but a part-time job should never interfere with study, and any tax must be paid as the law requires. Above all, students should spend in a rational way and never go beyond their agreed credit limit. By avoiding luxuries they do not really need, young people can stay afloat and enjoy their studies without constant worry about money.', '说明·学生理财', 155, '[{"q":"What is the main advice about saving money?","answer":"C","options":["Save everything and never spend at all.","Wait until you are rich before saving.","Save small amounts regularly and let them grow.","Put all your money into one big purchase."],"explanation":"对 ''saving a small amount each week and slowly increase it'' 的转述。"},{"q":"What rule about a part-time job does the writer give?","answer":"D","options":["It should replace all your classes.","It must pay more than the rent.","It should be done only at night.","It must not get in the way of studying."],"explanation":"对 ''a part-time job should never interfere with study'' 的转述。"},{"q":"What is the overall message of the passage?","answer":"A","options":["Manage money carefully so you do not fall into debt.","Borrow as much as the bank will allow.","Buy luxuries to feel happier at university.","Avoid opening any bank account."],"explanation":"全文主旨:养成理财好习惯、避免负债。"}]'::jsonb, '[{"word":"make ends meet","cn":"收支相抵"},{"word":"interest","cn":"利息"},{"word":"afloat","cn":"周转得开"}]'::jsonb, 2, 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Goodbye to Cash?', 'Fewer and fewer people carry cash today. Instead, they pay with cards, mobile phones and other electronic devices. Supporters of non-cash payment love how fast and easy it is. With a quick scan of a code, a bill is paid in the blink of an eye, and there is no need to carry heavy coins or worry about losing a purse. Shops and banks also find electronic records easier to manage. Yet not everyone is convinced. Some people worry about spending too much, because it feels less real to tap a phone than to hand over notes. Others point to safety: phones can be stolen or hacked, and criminals may copy personal information for their own use. There is also the problem of what happens when the Internet fails or a battery dies. For these reasons, some suggest that we should use cash less often rather than give it up completely.', '议论·无现金支付', 151, '[{"q":"Why do supporters like non-cash payment?","answer":"B","options":["It needs lots of heavy coins.","It is fast and very convenient.","It is the only legal way to pay.","It works without any phone or card."],"explanation":"对 ''love how fast and easy it is'' 的转述。"},{"q":"What safety problem is mentioned in the text?","answer":"C","options":["Cards are always free of any risk.","Notes can never be stolen.","Phones can be hacked and personal data copied.","Banks refuse to keep records."],"explanation":"对 ''phones can be stolen or hacked, and criminals may copy personal information'' 的转述。"},{"q":"What do some people finally suggest?","answer":"D","options":["Stop using phones to pay at once.","Return to carrying only coins.","Let banks decide how people pay.","Reduce how often we use cash instead of dropping it entirely."],"explanation":"对 ''use cash less often rather than give it up completely'' 的转述。"}]'::jsonb, '[{"word":"non-cash payment","cn":"无现金支付"},{"word":"purse","cn":"钱包"},{"word":"hack","cn":"黑客入侵"}]'::jsonb, 2, 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'Mark''s Coffee Shop', 'Last year my cousin Mark decided to (1)____ his own coffee shop in our small town. He had little money, so he asked the bank for a (2)____ to help him start. At first, business was (3)____, and only a few customers came each day. Mark did not give up. He worked hard to make the shop a (4)____ place where people wanted to stay. He chose beans of (5)____ quality and learned to make every cup with care. Slowly, word spread, and more people began to (6)____ his coffee. By the end of the year, he could (7)____ two part-time workers and even pay them a small (8)____ at Christmas. Mark says the most important (9)____ in his success was patience, and he warns that you must never (10)____ your customers down.', 133, 2, '[{"q":"1","answer":"A","options":["open","close","sell","lose"],"explanation":"open a coffee shop 开一家咖啡店。"},{"q":"2","answer":"B","options":["gift","loan","bill","tax"],"explanation":"ask the bank for a loan 向银行贷款。"},{"q":"3","answer":"C","options":["busy","free","slow","loud"],"explanation":"business was slow 生意冷清。"},{"q":"4","answer":"D","options":["terrible","empty","dark","pleasant"],"explanation":"a pleasant place 一个让人愿意停留的舒适地方。"},{"q":"5","answer":"A","options":["high","low","cheap","poor"],"explanation":"beans of high quality 高品质的咖啡豆。"},{"q":"6","answer":"B","options":["refuse","enjoy","throw","spill"],"explanation":"began to enjoy his coffee 开始喜欢上他的咖啡。"},{"q":"7","answer":"C","options":["scold","become","hire","remain"],"explanation":"hire two part-time workers 雇用两名兼职工。"},{"q":"8","answer":"D","options":["fine","debt","rule","bonus"],"explanation":"pay them a bonus 给他们发奖金。"},{"q":"9","answer":"A","options":["factor","mistake","problem","danger"],"explanation":"the most important factor 最重要的因素。"},{"q":"10","answer":"B","options":["put","let","take","get"],"explanation":"let your customers down 让顾客失望(固定搭配 let sb down)。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'Lily and Her Pocket Money', 'My sister Lily is very good at managing her (1)____. Every month our parents give her some pocket money, and she always makes a simple (2)____ before she spends anything. First she puts aside a small amount to (3)____ for the future, because she knows that savings (4)____ slowly over time. Then she decides how much she can spend without going into (5)____. Lily never buys (6)____ that she does not really need, such as expensive toys or sweets. If she wants something costly, she (7)____ for a few weeks until she has enough. She also keeps every (8)____ so that she can check what she has bought. Thanks to these habits, she can always (9)____ ends meet and still has a little left at the end of the month. I really should (10)____ her good example.', 137, 2, '[{"q":"1","answer":"C","options":["time","food","money","sleep"],"explanation":"managing her money 管理她的钱。"},{"q":"2","answer":"D","options":["joke","mess","noise","plan"],"explanation":"makes a simple plan 做一个简单的计划。"},{"q":"3","answer":"A","options":["save","waste","borrow","lose"],"explanation":"save for the future 为将来存钱。"},{"q":"4","answer":"B","options":["fall","grow","stop","break"],"explanation":"savings grow over time 存款随时间增长。"},{"q":"5","answer":"C","options":["water","sight","debt","fashion"],"explanation":"going into debt 负债。"},{"q":"6","answer":"D","options":["friends","hours","words","things"],"explanation":"buys things she does not need 买不需要的东西。"},{"q":"7","answer":"A","options":["waits","runs","sleeps","hides"],"explanation":"she waits for a few weeks 她会等几周。"},{"q":"8","answer":"B","options":["song","bill","photo","key"],"explanation":"keeps every bill 保留每一张单据。"},{"q":"9","answer":"C","options":["take","do","make","get"],"explanation":"make ends meet 收支相抵(固定搭配)。"},{"q":"10","answer":"D","options":["break","lose","sell","follow"],"explanation":"follow her good example 学习她的好榜样。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'Old Chen Sells Online', 'Old Chen grows apples in a village far from any big city. For many years he found it hard to (1)____ his fruit, because few buyers ever came so far. Everything changed when his daughter taught him to sell (2)____, using a phone and the Internet. Now customers from all over the country can (3)____ his apples with a single click. The fruit is fresh, the (4)____ is fair, and orders arrive every day. Chen no longer has to (5)____ his apples to traders for very little money. Instead, he sends them straight to families, which brings him a much better (6)____. The whole village has noticed his success, and other farmers have started to (7)____ his method. E-commerce has (8)____ new hope to this quiet place. "I never (9)____ that a small phone could change my life," Chen says with a smile, "but now my apples (10)____ to homes a thousand miles away."', 154, 2, '[{"q":"1","answer":"A","options":["sell","eat","plant","water"],"explanation":"hard to sell his fruit 很难卖出水果。"},{"q":"2","answer":"B","options":["alone","online","aloud","asleep"],"explanation":"sell online 在网上销售。"},{"q":"3","answer":"C","options":["throw","burn","order","hide"],"explanation":"order his apples 订购他的苹果。"},{"q":"4","answer":"D","options":["noise","weather","road","price"],"explanation":"the price is fair 价格公道。"},{"q":"5","answer":"A","options":["hand","sing","drive","sleep"],"explanation":"hand his apples to traders 把苹果交给中间商。"},{"q":"6","answer":"B","options":["problem","income","illness","mistake"],"explanation":"a better income 更好的收入。"},{"q":"7","answer":"C","options":["ignore","fear","copy","lose"],"explanation":"copy his method 模仿他的做法。"},{"q":"8","answer":"D","options":["lost","closed","broken","brought"],"explanation":"brought new hope 带来了新希望。"},{"q":"9","answer":"A","options":["imagined","refused","escaped","returned"],"explanation":"never imagined 从未想到。"},{"q":"10","answer":"B","options":["belong","travel","listen","point"],"explanation":"my apples travel to homes 我的苹果运往各家各户。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'Mei''s First Job', 'When Mei finished school, she took her first (1)____ at a flower company. On the first day she felt (2)____ and her hands were shaking, but she was determined to do well. Her job was to pack roses quickly before they lost their (3)____ smell. The work was hard, and the early (4)____ began before sunrise. Mei never (5)____, even when she was tired. Her manager soon noticed how (6)____ she worked and gave her more responsibility. At the end of the year, the company did very well, so every worker received a (7)____ as a reward. Mei was proud of the money she had (8)____ with her own effort. She used part of it to help her parents and (9)____ the rest in the bank. "Hard work always (10)____ off," she likes to say. "My first job taught me that."', 141, 2, '[{"q":"1","answer":"C","options":["sleep","meal","job","game"],"explanation":"her first job 她的第一份工作。"},{"q":"2","answer":"D","options":["lazy","sleepy","angry","nervous"],"explanation":"felt nervous 感到紧张。"},{"q":"3","answer":"A","options":["sweet","sour","loud","dark"],"explanation":"their sweet smell 它们香甜的气味。"},{"q":"4","answer":"B","options":["party","shift","lesson","match"],"explanation":"the early shift 早班。"},{"q":"5","answer":"C","options":["smiled","slept","complained","sang"],"explanation":"never complained 从不抱怨。"},{"q":"6","answer":"D","options":["badly","slowly","rarely","hard"],"explanation":"how hard she worked 她工作多么努力。"},{"q":"7","answer":"A","options":["bonus","bill","fine","debt"],"explanation":"received a bonus 得到一笔奖金。"},{"q":"8","answer":"B","options":["lost","earned","spent","borrowed"],"explanation":"the money she had earned 她挣来的钱。"},{"q":"9","answer":"C","options":["threw","broke","put","drove"],"explanation":"put the rest in the bank 把余下的钱存进银行。"},{"q":"10","answer":"D","options":["takes","falls","runs","pays"],"explanation":"hard work pays off 努力终有回报(固定搭配)。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'New Life for Green Hill', 'Ten years ago, the small town of Green Hill was losing its young people, who left to find work in the cities. Then the local people found a new way to (1)____ their home. They turned the clean rivers and green hills into a place for (2)____. Visitors now come to enjoy fresh air, walk in the forests and learn about country (3)____. The money these tourists spend has (4)____ new life to the town. Old houses have become guest rooms, and farmers now (5)____ their spare rooms to travellers. Many young people have (6)____ home to start small businesses, such as cafés and craft shops. The town is careful, however, not to (7)____ its natural beauty. Rules protect the rivers, and the number of visitors is (8)____ each day. "We want growth," the mayor says, "but we must also (9)____ the land for our children." Thanks to tourism, Green Hill has a brighter (10)____ once again.', 157, 2, '[{"q":"1","answer":"A","options":["save","sell","leave","forget"],"explanation":"save their home 拯救家乡。"},{"q":"2","answer":"B","options":["fighting","tourism","sleeping","crying"],"explanation":"a place for tourism 旅游胜地。"},{"q":"3","answer":"C","options":["war","debt","life","fear"],"explanation":"country life 乡村生活。"},{"q":"4","answer":"D","options":["lost","closed","sold","brought"],"explanation":"brought new life 带来了新生机。"},{"q":"5","answer":"A","options":["rent","throw","burn","hide"],"explanation":"rent their spare rooms 出租空闲房间。"},{"q":"6","answer":"B","options":["fallen","returned","sung","slept"],"explanation":"returned home 返回家乡。"},{"q":"7","answer":"C","options":["paint","count","harm","read"],"explanation":"not to harm its natural beauty 不破坏自然之美。"},{"q":"8","answer":"D","options":["painted","eaten","sung","limited"],"explanation":"the number of visitors is limited 游客数量受到限制。"},{"q":"9","answer":"A","options":["protect","sell","waste","leave"],"explanation":"protect the land 保护这片土地。"},{"q":"10","answer":"B","options":["debt","future","danger","mistake"],"explanation":"a brighter future 更光明的未来。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective4', 'U4', 'Cloth That Came Back', 'In a mountain village known for its beautiful cloth, an old craft was almost (1)____. Few young people wanted to learn the slow art of weaving, and the (2)____ for hand-made cloth had fallen. Then a young woman named Hua came back from the city with a new (3)____. She believed the village''s skill had great (4)____. Hua helped the weavers sell their work online and design products that modern buyers would (5)____. Soon orders began to (6)____ from cities far away. The weavers earned a better (7)____, and several poor families could finally (8)____ ends meet. Proud of their tradition, more young people chose to (9)____ the old skill instead of leaving home. Today the village is famous again, and its beautiful cloth has helped the local economy to (10)____.', 131, 2, '[{"q":"1","answer":"C","options":["born","paid","lost","sold"],"explanation":"almost lost 几乎失传。"},{"q":"2","answer":"D","options":["fear","noise","rain","demand"],"explanation":"the demand for cloth 对布料的需求。"},{"q":"3","answer":"A","options":["idea","fear","song","meal"],"explanation":"a new idea 一个新点子。"},{"q":"4","answer":"B","options":["danger","potential","debt","noise"],"explanation":"great potential 巨大的潜力。"},{"q":"5","answer":"C","options":["fear","burn","buy","drop"],"explanation":"products that buyers would buy 买家愿意购买的产品。"},{"q":"6","answer":"D","options":["sleep","cry","fall","arrive"],"explanation":"orders began to arrive 订单开始涌来。"},{"q":"7","answer":"A","options":["income","illness","mistake","danger"],"explanation":"a better income 更高的收入。"},{"q":"8","answer":"B","options":["take","make","do","get"],"explanation":"make ends meet 收支相抵。"},{"q":"9","answer":"C","options":["lose","sell","learn","leave"],"explanation":"learn the old skill 学习古老的手艺。"},{"q":"10","answer":"D","options":["fall","stop","close","grow"],"explanation":"helped the economy to grow 帮助经济发展(blossom)。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 Starting a Business', '外研社版选择性必修第四册 U4 · dialogue', 3, 'Lucy: Have you decided what to do after we graduate, Tom?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·独白 A Year-End Reward', '外研社版选择性必修第四册 U4 · passage', 2, 'Good afternoon, everyone. This has been a wonderful year for our flower company. Because we all worked so hard, our roses are now sold across Asia. To thank you, the company will give every worker a bonus this month. Those who arrived early to pick the flowers before sunrise will receive a little extra. We hope this reward shows how much we value your effort. Next year, with your help, we want to grow even more.', '下午好,各位。对我们花卉公司来说,这是了不起的一年。因为大家都很努力,我们的玫瑰如今已销往亚洲各地。为感谢大家,公司本月将给每位工人发奖金;那些日出前就来采花的人还会额外多得一点。希望这份奖励能体现我们对你们付出的重视。明年,有了大家的帮助,我们想发展得更好。', 'uk_female', '[{"q":"Why was it a good year for the company?","type":"choice","answer":"D","options":["The weather was unusually cold.","The company closed several shops.","Few flowers were grown.","Everyone worked hard and the roses sold widely."]},{"q":"What will every worker receive?","type":"choice","answer":"A","options":["A bonus.","A new house.","A free holiday abroad.","A company car."]},{"q":"Who will get a little extra money?","type":"choice","answer":"B","options":["Those who arrived late each day.","Those who came early to pick flowers.","Only the managers.","The newest workers."]},{"q":"When are the roses picked?","type":"choice","answer":"C","options":["Late at night.","Around noon.","Before sunrise.","After dinner."]},{"q":"What does the company hope for next year?","type":"choice","answer":"D","options":["To sell fewer roses.","To move to another country.","To stop hiring workers.","To grow even more."]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 Opening a Bank Account', '外研社版选择性必修第四册 U4 · dialogue', 3, 'Clerk: Good morning. How can I help you today?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·独白 The Joy of Sharing', '外研社版选择性必修第四册 U4 · passage', 2, 'The sharing economy lets people borrow things instead of buying them. With a phone, you can hire a bike for an hour or rent a room for a night. This saves money for both the lender and the borrower. It also helps the environment, because sharing means fewer cars on the road and less waste. Many people even make new friends while sharing. Of course, users must still protect their personal information. But for most people, sharing is a smart and friendly way to live.', '共享经济让人们借用而非购买物品。用手机,你可以租一辆自行车骑一小时,或租一个房间住一晚。这为出借者和借用者双方都省钱。它也有利于环境,因为共享意味着路上的车更少、浪费更少。许多人在共享中还结交了新朋友。当然,用户仍须保护个人信息。但对大多数人来说,共享是一种聪明又友好的生活方式。', 'uk_female', '[{"q":"What does the sharing economy let people do?","type":"choice","answer":"B","options":["Build their own factories.","Borrow things instead of buying them.","Stop using phones.","Throw old items away."]},{"q":"What can you hire with a phone?","type":"choice","answer":"C","options":["A plane or a ship.","A teacher or a doctor.","A bike or a room.","A farm or a forest."]},{"q":"Who saves money in this system?","type":"choice","answer":"D","options":["Only the lender.","Only the shops.","Nobody at all.","Both the lender and the borrower."]},{"q":"How does sharing help the environment?","type":"choice","answer":"A","options":["Fewer cars on the road and less waste.","More factories are built.","More cars are sold.","More trees are cut down."]},{"q":"What must users still do?","type":"choice","answer":"B","options":["Give away their phones.","Protect their personal information.","Pay a large yearly fee.","Stop making friends."]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·对话 At the Flower Market', '外研社版选择性必修第四册 U4 · dialogue', 3, 'Buyer: These roses look lovely. How much are they?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U4 听力·独白 Advice for Young Founders', '外研社版选择性必修第四册 U4 · passage', 2, 'If you dream of starting your own business, here is some advice. First, you need more than a good idea; you also need a clear plan and money to begin. Second, learn from people with more experience, and ask experts for guidance before you start. Third, work hard, but be realistic and know your own limits. Many young people fail because they are too ambitious. Remember, success takes time. With patience and careful planning, your small idea may one day grow into something great.', '如果你梦想自己创业,这里有几条建议。第一,光有好点子还不够,你还需要清晰的计划和启动资金。第二,向更有经验的人学习,起步前请教专家。第三,努力工作,但要现实,知道自己的极限。许多年轻人失败,是因为太好高骛远。记住,成功需要时间。凭借耐心和周密的计划,你的小点子也许有一天会成长为伟大的事业。', 'uk_female', '[{"q":"Besides a good idea, what else do you need?","type":"choice","answer":"D","options":["A large house and a car.","Many friends abroad.","A famous name.","A clear plan and money to begin."]},{"q":"Who should you learn from?","type":"choice","answer":"A","options":["People with more experience.","People who never worked.","Only your classmates.","Nobody at all."]},{"q":"Why do many young people fail?","type":"choice","answer":"B","options":["They never have ideas.","They are too ambitious.","They work too little.","They save too much."]},{"q":"What does success take, according to the speaker?","type":"choice","answer":"C","options":["Luck alone.","A lot of cash only.","Time and patience.","No planning at all."]},{"q":"What may a small idea become one day?","type":"choice","answer":"D","options":["A complete failure.","A waste of money.","A quiet hobby.","Something great."]}]'::jsonb, '[]'::jsonb, 'short', 'elective4', 'U4', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Introduce a Local Product Using Attributive Clauses(用定语从句介绍一款本地产品)', 'A Product Worth Trying', '假设你叫李华,学校英语角要做一期"家乡好物"分享。请用英语写一篇约80词的短文,介绍一款你喜欢的本地产品,内容包括:① 这是什么产品、产自哪里;② 它有什么特别之处(品质/做法/价格);③ 为什么推荐它。要求:恰当使用定语从句(who/which/that/whose/where 等),句子地道、围绕中心。', 'Suppose you are Li Hua. Your school English corner is holding a ''Local Treasures'' show. Write a short passage (about 80 words) to introduce a local product you like, including: 1) what it is and where it comes from; 2) what makes it special (quality, the way it is made, or price); 3) why you recommend it. Use attributive clauses (who/which/that/whose/where) where appropriate.', '["说明产品与产地(… , which comes from … / a place where …)","描述特别之处(made by farmers whose … / its taste, which …)","说明价格或意义(part of the money that you pay …)","给出推荐(a product you will not forget / I recommend …)"]'::jsonb, 70, 100, 'I''d like to introduce Rose Valley honey, which comes from a quiet valley where roses grow wild. The honey is made by local farmers, whose families have kept bees for years. What makes it special is its mild, sweet taste, which many customers love. Part of the money that you pay goes back to the workers who pick the flowers before sunrise. If you want a natural gift that supports a small business, this is a product you will not forget.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["I''d like to introduce Rose Valley honey, which comes from a quiet valley where roses grow wild.","The honey is made by local farmers, whose families have kept bees for years.","What makes it special is its mild, sweet taste, which many customers love.","If you want a natural gift that supports a small business, this is a product you will not forget."]'::jsonb, '[{"wrong":"the valley which roses grow wild","correct":"the valley where roses grow wild","note":"从句不缺主宾、只缺地点状语,用 where(= in which),不用 which。"},{"wrong":"farmers which keep bees","correct":"farmers who keep bees","note":"先行词指人,用 who/that,不用 which。"},{"wrong":"the honey, that is sweet, sells well","correct":"the honey, which is sweet, sells well","note":"非限制性定语从句(逗号)不能用 that,指物用 which。"}]'::jsonb, '【产品介绍·定语从句结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective4', 'U4', '{"title":"定语从句综合复习·关系词速查","intro":"定语从句修饰名词(先行词)。判断口诀:先看先行词指人还是指物,再看从句缺什么成分——缺主语/宾语用关系代词,缺状语用关系副词(= 介词+which)。逗号后的非限制性从句绝不用 that。","table":{"headers":["关系词","用法 / 例句"],"rows":[["who / whom","指人,作主语用 who、作宾语用 whom:the worker who came / the boss whom I trust"],["which","指物,作主语或宾语:the plan which won;介词后只能用 which:in which"],["that","指人或物(限制性);all/everything/the only/序数词后只能用 that;非限制性不用 that"],["whose","所有格(……的),指人指物皆可:the brand whose name is famous"],["when / where / why","从句缺状语:the day when = on which;the valley where = in which;the reason why = for which"]]},"specialRules":[{"rule":"从句缺主语/宾语 → 关系代词;只缺状语 → 关系副词(= 介词+which)","mark":"the valley where roses grow(缺地点状语→where)"},{"rule":"介词后只能用 which / whom,绝不用 that 或 where/when","mark":"in which √ / in that ×"},{"rule":"逗号后的非限制性从句不用 that;which 可指代前面整句话","mark":"She left, which surprised us."},{"rule":"of which / of whom 表部分:all/most/none/some of which(物)/ whom(人)","mark":"ten workers, all of whom …"},{"rule":"all/everything/the only/the first 等修饰先行词时只用 that","mark":"everything that he said"}],"why":["关系副词 = 介词 + which,本身在从句里作状语,所以从句主语、宾语都不缺;一旦主语或宾语缺了,就要换回关系代词 who/which/that。"],"gaokaoPoints":["关系代词 vs 关系副词的判断(看从句缺主宾还是缺状语):语法填空与改错高频。","非限制性从句用 which/who/whose(不用 that),which 还可指代整句话——语篇填空常考。","of which / of whom 与 as is known 等固定结构,书面表达加分。"],"examVsReal":[{"exam":"the house in which she lives（考试/正式）","real":"the house she lives in / the house where she lives","note":"口语常省略关系词、把介词放句末"},{"exam":"the reason why he succeeded（考试）","real":"the reason he succeeded / the reason that he succeeded","note":"口语里 why 常被省略或用 that"}]}'::jsonb, 'fltrp');
